CREATE INDEX accounts_company_kind_idx ON public.accounts USING btree (company_id, kind);

CREATE INDEX approval_requests_target_idx ON public.approval_requests USING btree (target_table, target_id);

CREATE INDEX areas_locations_city_code_idx ON public.areas_locations USING btree (city_id, code) WHERE ((deleted_at IS NULL) AND (code IS NOT NULL));

CREATE INDEX branches_super_admin_idx ON public.branches USING btree (is_super_admin) WHERE ((deleted_at IS NULL) AND (is_super_admin = true));

CREATE INDEX cities_country_code_idx ON public.cities USING btree (country_id, code) WHERE ((deleted_at IS NULL) AND (code IS NOT NULL));

CREATE INDEX cities_country_state_district_lookup_idx ON public.cities USING btree (country_id, state_province_id, district_id) WHERE (deleted_at IS NULL);

CREATE INDEX cities_district_active_name_idx ON public.cities USING btree (district_id, is_active, lower(name)) WHERE (deleted_at IS NULL);

CREATE INDEX cities_updated_by_idx ON public.cities USING btree (updated_by) WHERE (deleted_at IS NULL);

CREATE INDEX city_branches_area_idx ON public.city_branches USING btree (area_location_id) WHERE (deleted_at IS NULL);

CREATE INDEX city_branches_city_idx ON public.city_branches USING btree (city_id) WHERE (deleted_at IS NULL);

CREATE INDEX city_branches_email_idx ON public.city_branches USING btree (lower(email)) WHERE ((email IS NOT NULL) AND (deleted_at IS NULL));

CREATE INDEX city_branches_state_idx ON public.city_branches USING btree (state_province_id) WHERE (deleted_at IS NULL);

CREATE INDEX city_branches_whatsapp_idx ON public.city_branches USING btree (whatsapp_number) WHERE (whatsapp_number IS NOT NULL);

CREATE INDEX communication_center_campaigns_scope_idx ON public.communication_center_campaigns USING btree (country_id, country_branch_id, city_branch_id, status, created_at DESC) WHERE (deleted_at IS NULL);

CREATE INDEX communication_center_followups_due_idx ON public.communication_center_followups USING btree (status, due_at) WHERE (deleted_at IS NULL);

CREATE INDEX communication_center_leads_scope_idx ON public.communication_center_leads USING btree (country_id, country_branch_id, city_branch_id, status, created_at DESC) WHERE (deleted_at IS NULL);

CREATE INDEX communication_center_messages_document_idx ON public.communication_center_messages USING btree (linked_module, linked_document_no) WHERE (deleted_at IS NULL);

CREATE INDEX communication_center_messages_scope_idx ON public.communication_center_messages USING btree (country_id, country_branch_id, city_branch_id, channel, folder, created_at DESC) WHERE (deleted_at IS NULL);

CREATE INDEX communication_center_profiles_scope_idx ON public.communication_center_profiles USING btree (scope, country_id, country_branch_id, city_branch_id) WHERE (deleted_at IS NULL);

CREATE INDEX companies_city_id_idx ON public.companies USING btree (city_id) WHERE (deleted_at IS NULL);

