CREATE TRIGGER products_sync_scope_mappings_trg AFTER INSERT OR UPDATE OF country_id, state_province_id, city_id, country_branch_id, city_branch_id ON public.products FOR EACH ROW WHEN ((new.deleted_at IS NULL)) EXECUTE FUNCTION sync_product_scope_mappings();

